import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI 协议（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/uri-protocol.md","filePath":"zh-CN/user-guide/uri-protocol.md","lastUpdated":1785993908000}'),d={name:"zh-CN/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="uri-协议-lertaro" tabindex="-1">URI 协议（lertaro://） <a class="header-anchor" href="#uri-协议-lertaro" aria-label="Permalink to &quot;URI 协议（lertaro://）&quot;">​</a></h1><p>Lertaro 会自动把自己注册为 <code>lertaro://</code> 链接的处理程序——不需要额外的安装步骤，第一次运行时就会自动完成注册。这样任何能打开链接的东西（浏览器、快捷方式、别的程序、脚本）都能直接跳到 Lertaro 的某个具体位置，而不是只能靠热键触发。</p><p>如果 Lertaro 还没运行，打开一个 <code>lertaro://</code> 链接会先启动它，再执行这个链接指向的操作。如果已经在运行，正在运行的那个实例会直接处理这个链接——不会再启动第二份进程。</p><h2 id="支持的链接" tabindex="-1">支持的链接 <a class="header-anchor" href="#支持的链接" aria-label="Permalink to &quot;支持的链接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>链接</th><th>作用</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>激活快速搜索窗口——效果和用热键呼出它一样。</td></tr><tr><td><code>lertaro://search/[关键词]</code></td><td>激活快速搜索窗口，并预填 <code>[关键词]</code>。</td></tr><tr><td><code>lertaro://fullsearch/[关键词]</code></td><td>打开完整搜索窗口，并预填 <code>[关键词]</code>。</td></tr><tr><td><code>lertaro://settings/page/[分区]</code></td><td>打开设置窗口，并切到指定的顶层分区。</td></tr><tr><td><code>lertaro://settings/entry/[序号]</code></td><td>打开设置窗口，并直接跳转到某一项具体设置，并高亮显示。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>第一个会激活快速搜索窗口，并已经用&quot;report&quot;过滤好；第二个会直接打开设置窗口的&quot;外观&quot;页。</p><p><code>[分区]</code> 对应侧边栏顶层的某一项：<code>Service</code>、<code>Index</code>、<code>General</code>、<code>Appearance</code>、<code>Hotkeys</code>、 <code>Plugins</code>、<code>Favorites</code>、<code>History</code>、<code>QuickPanel</code>、<code>About</code>——不区分大小写。</p><p><code>[序号]</code> 不是给人手动输入用的——它是<a href="./instant-answers.html">设置搜索</a>在你选中某项设置结果时自己生成的一个数字，选中结果会自动带上这个序号，原样跳转回那一项设置。这个序号在重启之间并不稳定，不要指望某个具体数字每次都对应同一项设置。</p><h2 id="无法识别的链接" tabindex="-1">无法识别的链接 <a class="header-anchor" href="#无法识别的链接" aria-label="Permalink to &quot;无法识别的链接&quot;">​</a></h2><p>任何匹配不上已知路由的链接——打错了字、分区不存在、<code>lertaro://</code> 后面跟了一堆乱七八糟的内容——都会被直接忽略。由于任何网站或程序都能在你不知情的情况下调起这个协议，一个错误或异常的链接不应该产生任何出人意料的效果；这类情况只会记进日志方便你自己排查，除此之外什么都不会发生。</p>`,11)])])}const _=t(d,[["render",c]]);export{u as __pageData,_ as default};
